const CATALOGS = new Map([
  ['en', ENGLISH_MESSAGES],
  ['zh-Hans', ZH_HANS_MESSAGES],
  ['zh-Hant', ZH_HANT_MESSAGES],
  ['ja', JA_MESSAGES],
  ['ko', KO_MESSAGES],
  ['es', ES_MESSAGES],
  ['fr', FR_MESSAGES],
  ['de', DE_MESSAGES],
  ['pt-BR', PT_BR_MESSAGES],
  ['ar', AR_MESSAGES],
  ['hi', HI_MESSAGES],
  ['id', ID_MESSAGES],
  ['ru', RU_MESSAGES],
  ['th', TH_MESSAGES],
  ['tr', TR_MESSAGES],
  ['vi', VI_MESSAGES],
]);

const SHARED_LITERAL_KEYS = new Set([
  'corpus_status', 'endpoint', 'model', 'p50', 'column_status',
  'column_action', 'column_impact', 'column_type', 'valid', 'nav_governance',
  // Spanish spells this query class exactly as English does; forcing a synonym would make the
  // label less accurate just to satisfy the untranslated-message check.
  'page_title', 'brand_name', 'class_error',
]);

function placeholders(value) {
  return [...String(value).matchAll(/\{([a-z][a-z0-9_]*)\}/giu)].map(match => match[1]).sort();
}

function canonicalLocaleCandidate(value) {
  if (!value) return null;
  try {
    const locale = new Intl.Locale(String(value).replaceAll('_', '-'));
    const language = locale.language.toLowerCase();
    if (language === 'zh') {
      const script = locale.script?.toLowerCase();
      const region = locale.region?.toUpperCase();
      return script === 'Hant'.toLowerCase() || ['TW', 'HK', 'MO'].includes(region) ? 'zh-Hant' : 'zh-Hans';
    }
    if (language === 'pt') return 'pt-BR';
    return MEMORY_DASHBOARD_LOCALES.find(item => item.toLowerCase() === language) || null;
  } catch {
    return null;
  }
}

function acceptLanguageCandidates(header) {
  return String(header || '').split(',').map((entry, order) => {
    const [tag, ...parameters] = entry.trim().split(';');
    const qualityParameter = parameters.find(item => item.trim().startsWith('q='));
    const quality = qualityParameter ? Number(qualityParameter.trim().slice(2)) : 1;
    return { tag, quality: Number.isFinite(quality) ? quality : 0, order };
  }).filter(item => item.tag && item.quality > 0)
    .sort((left, right) => right.quality - left.quality || left.order - right.order)
    .map(item => item.tag);
}

export function negotiateMemoryDashboardLocale({ requested, acceptLanguage } = {}) {
  const requestedLocale = canonicalLocaleCandidate(requested);
  if (requestedLocale) return requestedLocale;
  for (const candidate of acceptLanguageCandidates(acceptLanguage)) {
    if (candidate === '*') break;
    const matched = canonicalLocaleCandidate(candidate);
    if (matched) return matched;
  }
  return 'en';
}

export function memoryDashboardCatalog(locale) {
  const selected = canonicalLocaleCandidate(locale) || 'en';
  const messages = Object.freeze({
    ...(CATALOGS.get(selected) || ENGLISH_MESSAGES),
    page_title: 'OwnMem Console',
    brand_name: 'OwnMem',
  });
  return Object.freeze({
    locale: selected,
    direction: LOCALE_META[selected].direction,
    nativeName: LOCALE_META[selected].nativeName,
    locales: MEMORY_DASHBOARD_LOCALES.map(id => ({ id, ...LOCALE_META[id] })),
    messages,
  });
}

/**
 * The per-locale rules, separated from the shipped catalogs so they can be run against a
 * deliberately broken one.
 *
 * Auditing only the real catalogs proves those catalogs are currently clean. It cannot prove the
 * rules would still object once they stopped being clean, and that gap was real: on 2026-08-15
 * every one of these checks was disabled in turn and the whole suite stayed green, including the
 * one that keeps raw HTML out of a message the dashboard interpolates.
 *
 * `reference` is the key set and placeholder contract every locale is measured against.
 */
export function auditMemoryDashboardCatalogEntry(locale, messages, reference = ENGLISH_MESSAGES) {
  if (!messages) return [{ locale, code: 'missing-catalog' }];
  const issues = [];
  const expected = Object.keys(reference).sort();
  const actual = Object.keys(messages).sort();
  const missing = expected.filter(key => !actual.includes(key));
  const extra = actual.filter(key => !expected.includes(key));
  if (missing.length) issues.push({ locale, code: 'missing-keys', keys: missing });
  if (extra.length) issues.push({ locale, code: 'extra-keys', keys: extra });
  for (const key of expected) {
    if (typeof messages[key] !== 'string' || !messages[key].trim()) {
      issues.push({ locale, code: 'empty-message', key });
    }
    if (/[<>]/u.test(messages[key] || '')) issues.push({ locale, code: 'html-in-message', key });
    if (/[—–]/u.test(messages[key] || '')) issues.push({ locale, code: 'disallowed-dash', key });
    if (placeholders(messages[key]).join(',') !== placeholders(reference[key]).join(',')) {
      issues.push({ locale, code: 'placeholder-mismatch', key });
    }
    if (locale !== 'en' && messages[key] === reference[key] && !SHARED_LITERAL_KEYS.has(key)) {
      issues.push({ locale, code: 'untranslated-message', key });
    }
  }
  if (locale === 'ar' && LOCALE_META[locale].direction !== 'rtl') issues.push({ locale, code: 'direction-mismatch' });
  return issues;
}

/**
 * `catalogs` overrides the audited source and exists only so the aggregate verdict can be proven
 * against a catalog set that is actually broken. The release gate consumes `valid`, not `issues`,
 * so a `valid` that cannot go false is a gate that cannot fail -- and with the real catalogs as the
 * only input, no test can tell the two apart. Callers pass nothing; the default is unchanged.
 */
export function auditMemoryDashboardCatalogs({ catalogs = null } = {}) {
  const expected = Object.keys(ENGLISH_MESSAGES).sort();
  const source = catalogs
    || new Map(MEMORY_DASHBOARD_LOCALES.map(locale => [locale, memoryDashboardCatalog(locale).messages]));
  const issues = [];
  for (const [locale, messages] of source) issues.push(...auditMemoryDashboardCatalogEntry(locale, messages));
  return { schema: 'ownmem-dashboard-i18n-audit/v1', locales: source.size, keys: expected.length, issues, valid: issues.length === 0 };
}
